CREATE TABLE md_datasets(id TEXT PRIMARY KEY,owner_id BIGINT NOT NULL CHECK(owner_id>0),name TEXT NOT NULL,format TEXT NOT NULL CHECK(format IN ('csv','parquet')),raw BYTEA NOT NULL,columns JSONB NOT NULL,preview JSONB NOT NULL,current_version TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX md_owner ON md_datasets(owner_id,id DESC);
CREATE TABLE md_versions(id TEXT PRIMARY KEY,dataset_id TEXT NOT NULL REFERENCES md_datasets(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('uploaded','mapped','indexing','ready','failed')),mapping JSONB,row_count INTEGER NOT NULL DEFAULT 0,csv TEXT NOT NULL DEFAULT '',sha256 TEXT NOT NULL DEFAULT '',error TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(dataset_id,id));
CREATE TABLE md_points(dataset_id TEXT NOT NULL,version_id TEXT NOT NULL,ts TIMESTAMPTZ NOT NULL,o NUMERIC(38,18) NOT NULL,h NUMERIC(38,18) NOT NULL,l NUMERIC(38,18) NOT NULL,c NUMERIC(38,18) NOT NULL,v NUMERIC(38,18) NOT NULL,CHECK(o>0 AND h>=o AND h>=c AND l<=o AND l<=c AND l>0 AND v>=0),PRIMARY KEY(dataset_id,version_id,ts),FOREIGN KEY(dataset_id,version_id) REFERENCES md_versions(dataset_id,id) ON DELETE CASCADE);
CREATE TABLE md_jobs(id TEXT PRIMARY KEY,owner_id BIGINT NOT NULL,dataset_id TEXT NOT NULL REFERENCES md_datasets(id) ON DELETE CASCADE,version_id TEXT NOT NULL REFERENCES md_versions(id) ON DELETE CASCADE,key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed')),claim_token TEXT NOT NULL DEFAULT '',lease_until TIMESTAMPTZ,error TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(owner_id,key));
CREATE INDEX md_queue ON md_jobs(created_at) WHERE status='queued';
CREATE FUNCTION md_immutable_ready_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='ready' THEN RAISE EXCEPTION 'ready dataset versions are immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER md_ready_immutable BEFORE UPDATE ON md_versions FOR EACH ROW EXECUTE FUNCTION md_immutable_ready_version();
